{
  "research_concepts": [
    "player absence",
    "offensive reorganization",
    "baseline window L",
    "change in points per possession",
    "play type and initiator distribution",
    "absorption versus cascade after a player sits",
    "lineup spells"
  ],
  "methodological_questions": [
    "Is 'offensive reorganization relative to L' defined precisely enough to measure, given that L and the reorganization index are not specified in the task?",
    "What is the unit of analysis, given that the data list n=986 and n=148 spells?",
    "Can a reorganization measure built from play-by-play be separated from the points per possession outcome it is meant to predict?",
    "Does the spell-level sample have enough power to detect a plausible effect (the stated MDE rho is not given numerically)?",
    "Are play-type and initiator labels accurate enough to support the measure?"
  ],
  "historical_evidence": [
    {
      "id": "FAM:SF-CHT-052",
      "status_as_recorded": "inconclusive",
      "finding": "Closest prior question: tested whether play-type replacement similarity separates absorption from cascade when a player sits. Mean similarity was +0.863 for ABSORBED vs +0.848 for CASCADE, and Spearman(sim, -gap) was -0.19 (wrong-signed). Recorded failure type is B_powered_null, with a label or classification error limitation. Sample and power were not recorded."
    },
    {
      "id": "FAM:SF38",
      "status_as_recorded": "inconclusive",
      "finding": "Tested defensive in-game adaptation to repeated play type. League-wide within-game slope was -0.0019 PPP per exposure (SE 0.0019), and across-game +0.0004 (SE 0.0015). Only PULL_UP survived Holm correction (-0.0243, Holm p 0.0004). Team-trait split-half r was +0.008. Limitations recorded: insufficient exposure, label or classification error, low measurement reliability."
    },
    {
      "id": "FAM:SF-APPM-014",
      "status_as_recorded": "not a hypothesis test",
      "finding": "Audit of inferred play-type labels failed overall. OTHER was 20.2% against a target below 10%, 40.8% of labels were low confidence, DRIVE foul-draw was 1.7% against a 14-22% benchmark, and team identity checks failed for MIA. Foul possessions leak into OTHER. Verdict: tool_eval_fail."
    },
    {
      "id": "FAM:SF-APPS-058",
      "status_as_recorded": "untestable",
      "finding": "Attempted on-ball scheme labels (DROP/ICE/SWITCH). Only 14.9% of DET on-ball possessions (10 of 67) and 3.3% of ORL possessions (2 of 60) were labelled. The switches_on field was unpopulated. Verdict: failed_gate."
    },
    {
      "id": "FAM:SF-APPA-017",
      "status_as_recorded": "rejected",
      "finding": "A5 routing effect shrank from +0.94 pts/100 at V5 to +0.03 pts/100 on the larger 520-matchup sample. Recorded as a powered null. Outcomes were model-scored, not observed."
    },
    {
      "id": "FAM:SF-PAP-042",
      "status_as_recorded": "rejected",
      "finding": "Tested for systematic volume pivots toward a better same-game play type across 1,539 triggers. The paper reports zero significant pivots. A looser flag gave adapts=True on 334 of 1,539 rows. Recorded as a powered null."
    },
    {
      "id": "FAM:SF-CHT-063",
      "status_as_recorded": "artifact",
      "finding": "A BEST-vs-continue gap after a slump (+0.248, SE 0.009) was the same without a slump (+0.239) and under a fixed CUT-heavy ranking (+0.238). Recorded as an artifact produced by the construction. Included as a warning about construction-driven gaps."
    },
    {
      "id": "FAM:SF-PAP-008",
      "status_as_recorded": "inconclusive",
      "finding": "Shaper presence and non-focal play-type entropy: d_entropy_nonfocal = -0.0455 (n_ts=80), with no uncertainty reported. Recorded as a null, interpreted as rebalancing rather than expansion."
    },
    {
      "id": "FAM:SF-APPS-071",
      "status_as_recorded": "not a hypothesis test",
      "finding": "Memoryless Monte Carlo generative check (10,000 games x 200 possessions). Simulated PPP SD 1.152 vs real 1.149, lag-1 scoring autocorrelation +0.0029 vs real -0.0022. It is an existence proof only, not independent evidence."
    },
    {
      "id": "FAM:SF-APPS-015",
      "status_as_recorded": "not a hypothesis test",
      "finding": "Descriptive tier tendencies over 55 series, 179 players, min 10 possessions per player. No outcome test."
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-CHT-052",
      "what_failed": "Using play-type replacement similarity to separate absorption of a departed player's usage from cascade to teammates.",
      "why": "Similarity did not separate absorb from cascade, and the sign was wrong. Recorded as B_powered_null with a label or classification error limitation."
    },
    {
      "id": "FAM:SF-APPM-014",
      "what_failed": "Inferring play-type labels from play-by-play and validating them against benchmark volumes, foul rates and team identities.",
      "why": "The audit failed. OTHER was too large, foul possessions leaked into OTHER, and identity checks failed. Recorded as C_artifact with label error and leakage limitations."
    },
    {
      "id": "FAM:SF-APPS-058",
      "what_failed": "Labelling on-ball defensive coverage from matchup fields.",
      "why": "Labels were populated for only 14.9% and 3.3% of on-ball possessions, and switches_on was unpopulated. Recorded as A_unanswerable."
    },
    {
      "id": "FAM:SF38",
      "what_failed": "Estimating an in-game exposure slope for repeated play types.",
      "why": "Effects were near zero and insufficient exposure, label error and low reliability were recorded. Only one play type survived correction."
    },
    {
      "id": "FAM:SF-APPA-017",
      "what_failed": "A routing gain that looked meaningful on a small sample.",
      "why": "The estimate shrank from +0.94 to +0.03 on a larger sample. Recorded as B_powered_null. This indicates early estimates on small samples are unreliable."
    },
    {
      "id": "FAM:SF-CHT-063",
      "what_failed": "A gap interpreted as costly failure to abandon a suppressed play.",
      "why": "The gap was unchanged with no slump condition and under a fixed ranking. Recorded as C_artifact, produced by the construction."
    }
  ],
  "evidence_establishes": [
    "A closely related absorb-versus-cascade question after a player sits returned no separation in similarity (SF-CHT-052), so a similarity-based reorganization index has no recorded support.",
    "Play-type labels inferred from this kind of play-by-play have failed audit on volume, foul and identity checks (SF-APPM-014). Any reorganization measure built from those labels inherits that risk.",
    "Effects estimated on small samples in this project have shrunk substantially on larger samples (SF-APPA-017), so an early or small-spell estimate should not be relied on.",
    "Construction-driven gaps can mimic effects (SF-CHT-063), so the measure needs a placebo or invariance check before any effect is read as real.",
    "The question as posed does not define L, the reorganization index, or the MDE rho. The retrieved records do not measure this quantity."
  ],
  "evidence_does_not_establish": [
    "Whether offensive reorganization relative to L predicts change in PPP. No retrieved record tests this quantity directly.",
    "Any effect size, direction, or power for the 148-spell sample.",
    "Whether the on-ball scheme, defensive adaptation, or routing findings transfer to offensive reorganization after absence.",
    "Whether the 2025-26 partial data are usable; the record set does not say.",
    "Whether the 986 units and the 148 spells are the same unit or nested units."
  ],
  "own_inferences": [
    "The question as posed is not operational. Without a fixed L and a reorganization index, no test can be pre-registered.",
    "If reorganization is measured from the same play-by-play as PPP, the two are partly mechanically linked, so a positive association could be produced by construction (OUTCOME_DERIVED_LABEL).",
    "With 148 spells, the study is likely underpowered for the small effects that the closest records suggest (SF-CHT-052, SF-PAP-042), so a null result is the most likely outcome."
  ],
  "uncertainties": [
    "The numeric MDE rho is missing.",
    "The unit (spell, team-game, or player-game) and the meaning of n=986 versus 148 spells are unclear.",
    "No retrieved record measures offensive reorganization after absence directly, so the prior evidence is indirect.",
    "Sample and power were not recorded for SF-CHT-052.",
    "Whether the play-type labels in the 2022-23 to 2025-26 files pass the audit in SF-APPM-014 is not recorded for this data version."
  ],
  "historical_effect": {
    "changed_decision": "yes",
    "explanation": "The retrieved records show that play-type labels have failed audit (SF-APPM-014), that a closely related absorb/cascade measure showed no separation (SF-CHT-052), and that small-sample effects shrink (SF-APPA-017). Together these lower the chance that a reorganization measure built from the same play-by-play can be tested cleanly. The decision moved from a possible proceed to do_not_proceed as posed, with a conditional minimum viable test."
  },
  "testability": {
    "p_testable": 0.25,
    "blocking_constraints": [
      {
        "code": "OUTCOME_DERIVED_LABEL",
        "text": "Reorganization and points per possession both come from the same play-by-play, so the predictor may be partly defined by the outcome."
      },
      {
        "code": "LABEL_ERROR",
        "text": "Play-type labels failed audit (SF-APPM-014), and the closely related absorb/cascade test was limited by label error (SF-CHT-052)."
      },
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "148 spells with an unspecified MDE rho is likely underpowered for small effects; the prior routing effect shrank on larger samples (SF-APPA-017)."
      },
      {
        "code": "MEASURE_RELIABILITY",
        "text": "Measurement reliability for team-level and season-level traits was low in the comparable defensive test (SF38)."
      }
    ]
  },
  "prior_work": {
    "already_answered": "partly",
    "cited": [
      "FAM:SF-CHT-052",
      "FAM:SF38",
      "FAM:SF-APPM-014",
      "FAM:SF-PAP-042"
    ],
    "summary": "No retrieved record tests offensive reorganization relative to L against change in PPP. The closest work asks whether similarity of replacement players separates absorption from cascade (SF-CHT-052, inconclusive, wrong-signed). Related work on play-type volume shifts (SF-PAP-042) found no systematic pivots on 1,539 triggers, which is a powered null for a neighbouring question. The play-type labels that any reorganization measure would depend on failed audit (SF-APPM-014). The question is therefore partly addressed by neighbouring evidence, not answered."
  },
  "risks": [
    {
      "code": "OUTCOME_DERIVED_LABEL",
      "text": "Reorganization and PPP are both derived from play-by-play; a positive association may be built in."
    },
    {
      "code": "LABEL_ERROR",
      "text": "Inferred play types failed audit (SF-APPM-014); on-ball labels were sparse (SF-APPS-058)."
    },
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "148 spells is likely too few for a small effect; the MDE rho is missing."
    },
    {
      "code": "MEASURE_RELIABILITY",
      "text": "Reliability of team and season traits was low in the closely related defensive analysis (SF38)."
    },
    {
      "code": "CONFOUNDING",
      "text": "Minutes, starter status, opponent quality, pace and shot quality may drive both reorganization and PPP changes."
    },
    {
      "code": "RTM_SELECTION",
      "text": "Spells selected because a player was absent may be non-random with respect to team quality or injury type."
    },
    {
      "code": "LEAKAGE_LOOKAHEAD",
      "text": "If L is computed using data that includes the spell or the outcome window, the baseline is contaminated."
    },
    {
      "code": "DRIFT_NONSTATIONARITY",
      "text": "Offensive styles changed across 2022-23 to 2025-26; pooling seasons without season controls may mix regimes."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "Many possible reorganization definitions and play-type splits invite selective reporting."
    },
    {
      "code": "PLACEBO_DEPENDENCE",
      "text": "Constructed gaps can be artifacts (SF-CHT-063); a placebo is required before any effect is read as real."
    },
    {
      "code": "IMPLEMENTATION_BUG",
      "text": "Partial 2025-26 playoff data and partial regular-season data before 2026-04-13 could enter the sample by mistake."
    }
  ],
  "predicted_outcome": {
    "supported": 0.08,
    "rejected": 0.17,
    "untestable": 0.35,
    "artifact": 0.15,
    "uncertain": 0.25
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "Not estimable as posed. Minimum viable estimand: the association between a pre-registered reorganization index (change in teammates' play-type or shot-location distribution during an absence spell, relative to a fixed pre-spell baseline window L) and the change in offensive points per possession for the team, with a placebo window at the same spell length before absence.",
    "unit": "Absence spell (player-team-spell), with a stated rule for overlapping spells and for players absent more than once.",
    "sample": "Regular-season spells from 2022-23 to 2025-26 only. Exclude the partial 2025-26 regular season before 2026-04-13 and the partial 2025-26 playoffs before 2026-06-21. Playoffs are held out. The sample is 148 spells unless the unit is redefined; the n=986 figure must be reconciled with the spell count before analysis.",
    "power": "Compute the minimum detectable rho for 148 spells at alpha 0.05 and 80% power before analysis. If the MDE is larger than any effect the closest records suggest, record the test as underpowered in advance.",
    "controls": "Minutes, starter status, team and opponent strength, pace, shot quality, season fixed effects, and team-season fixed effects. Use an independent source for play-type labels where the play-by-play-derived labels fail audit.",
    "falsification": "Placebo baseline windows that do not overlap the spell; the same reorganization index against non-absent teammates' PPP; and a label-audit gate (SF-APPM-014 criteria) that must pass before analysis.",
    "multiplicity": "One pre-registered primary reorganization index and one primary outcome. All other definitions are reported as exploratory, with correction across them.",
    "decision_rule": "Support requires a pre-registered positive association with a 95% CI excluding zero, surviving the placebo and label-audit checks. Rejection requires a CI that excludes effects larger than the stated MDE. Anything else is reported as uncertain.",
    "data_version": "Data as of 2026-11-01, with the complete-data cutoffs stated above. The label audit and the spell count reconciliation must be recorded against this version."
  }
}

